class Logger {
  constructor(prefix = '') {
    this.prefix = prefix;
  }
  info(m) {
    console.log(`${this.prefix}[info] ${m}`);
  }
  warn(m) {
    console.warn(`${this.prefix}[warn] ${m}`);
  }
  child(prefix) {
    return new Logger(this.prefix + prefix);
  }
}
module.exports = new Logger();
module.exports.Logger = Logger;

